class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        vector<int> res;
        while (!matrix.empty()) {
            res.insert(res.end(), matrix[0].begin(), matrix[0].end());  // 拿走第一行
            matrix.erase(matrix.begin());
            // 剩下的逆时针转 90°：从最右一列开始，每一列变成新的一行
            vector<vector<int>> next;
            int cols = matrix.empty() ? 0 : matrix[0].size();
            for (int c = cols - 1; c >= 0; c--) {
                vector<int> row;
                for (auto& r : matrix) {
                    row.push_back(r[c]);
                }
                next.push_back(row);
            }
            matrix = next;
        }
        return res;
    }
};

